const src = $json || {};
const query = src.query || {};
const body = typeof src.body === 'object' && src.body ? src.body : {};
return [{
  json: {
    pack_id: body.pack_id || query.pack_id || src.pack_id || '',
    internal_email_to: body.internal_email_to || query.internal_email_to || $env.POST_AUDIT_INTERNAL_EMAIL || 'contact@transferai.ci',
    next_action_delay_days: body.next_action_delay_days || query.next_action_delay_days || '1',
    trigger_source: 'webhook'
  }
}];

const src = $json || {};
return [{
  json: {
    pack_id: String(src.pack_id || '').trim(),
    internal_email_to: String(src.internal_email_to || 'contact@transferai.ci').trim(),
    next_action_delay_days: Number(src.next_action_delay_days || 1),
    trigger_source: src.trigger_source || 'manual'
  }
}];

const request = $('Normalize Post-Audit Request').first().json || {};
const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [];
const row = rows[0] || {};
const payload = row.payload || {};
return [{
  json: {
    ...request,
    row_id: row.id || null,
    pack_id: row.pack_id || payload.pack_id || request.pack_id || null,
    prospect_id: row.prospect_id || payload.prospect_id || null,
    organization_name: row.organization_name || payload.organization_name || null,
    target_email: row.target_email || payload.target_email || null,
    status: row.status || null,
    payload
  }
}];

const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [];
const row = rows[0] || {};
return [{
  json: {
    response_id: row.id || null,
    pack_id: row.pack_id || $('Extract Pack Row').first().json.pack_id || null,
    form_data: row.form_data || {},
    context_snapshot: row.context_snapshot || {},
    submitted_at: row.submitted_at || row.updated_at || null,
    updated_at: row.updated_at || null,
    raw_form_response: row
  }
}];

const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [];
const row = rows[0] || {};
return [{
  json: {
    prospect_id: row.prospect_id || $('Extract Pack Row').first().json.prospect_id || null,
    status: row.status || null,
    paused: Boolean(row.paused),
    do_not_contact: Boolean(row.do_not_contact),
    outreach_attempt_count: Number(row.outreach_attempt_count || 0),
    last_response_status: row.last_response_status || '',
    last_sequence_result: row.last_sequence_result || '',
    stop_reason: row.stop_reason || '',
    niche_status: row.niche_status || '',
    next_action_at: row.next_action_at || null,
    last_pack_id: row.last_pack_id || null,
    raw_prospect_target: row
  }
}];

const pack = $('Extract Pack Row').first().json || {};
const form = $('Extract Latest Form Response').first().json || {};
const prospect = $('Extract Prospect Target Row').first().json || {};
const payload = pack.payload || {};
const formData = form.form_data || {};
const contextSnapshot = form.context_snapshot || {};
const recommendation = formData.transferai_recommendation || contextSnapshot.transferai_recommendation || null;
const delayDays = Number(pack.next_action_delay_days || 1);
const nextActionAt = new Date(Date.now() + delayDays * 86400000).toISOString();
return [{
  json: {
    pack_id: pack.pack_id || null,
    prospect_id: pack.prospect_id || prospect.prospect_id || null,
    internal_email_to: pack.internal_email_to || 'contact@transferai.ci',
    trigger_source: pack.trigger_source || 'manual',
    organization_name: formData.c_entite || payload.organization_name || pack.organization_name || null,
    decision_maker_name: formData.c_nom || payload.decision_maker_name || null,
    target_email: formData.c_email || payload.target_email || pack.target_email || null,
    website: payload.website || null,
    country: payload.country || null,
    organization_type: formData.organization_type || payload.organization_type || null,
    sector_guess: formData.audit_sector || payload.sector_guess || null,
    prospect_language: payload.prospect_language || 'fr',
    commercial_priority_tier: payload.commercial_priority_tier || null,
    recommended_offer: payload.recommended_offer || null,
    recommended_use_case: payload.recommended_use_case || null,
    best_selling_use_case: payload.best_selling_use_case || null,
    audit_form_url: payload.audit_form_url || null,
    submitted_at: form.submitted_at || null,
    transferai_recommendation: recommendation,
    crm_status_before: prospect.status || null,
    crm_last_response_status_before: prospect.last_response_status || '',
    crm_last_sequence_result_before: prospect.last_sequence_result || '',
    crm_niche_status_before: prospect.niche_status || '',
    crm_next_action_at_before: prospect.next_action_at || null,
    crm_next_action_at_after: nextActionAt,
    form_data: formData,
    context_snapshot: contextSnapshot,
    pack_payload: payload,
    raw_form_response: form.raw_form_response || {},
    raw_prospect_target: prospect.raw_prospect_target || {}
  }
}];

const ctx = $('Build Post-Audit CRM Context').first().json || {};
const briefResponse = $('Generate Internal Pre-RDV Brief').first().json || {};
const brief = (((briefResponse.choices || [])[0] || {}).message || {}).content || '';
const resend = $('Send Internal Brief Email').first().json || {};
const resendId = resend.id || (resend.data && resend.data.id) || null;
return [{
  json: {
    status: 'post_audit_processed',
    pack_id: ctx.pack_id || null,
    prospect_id: ctx.prospect_id || null,
    organization_name: ctx.organization_name || null,
    submitted_at: ctx.submitted_at || null,
    primary_service: ctx.transferai_recommendation?.primary?.title || ctx.recommended_offer || null,
    secondary_service: ctx.transferai_recommendation?.secondary?.title || null,
    confidence_label: ctx.transferai_recommendation?.confidenceLabel || null,
    next_action_at: ctx.crm_next_action_at_after || null,
    internal_email_to: ctx.internal_email_to || null,
    resend_id: resendId,
    brief_markdown: brief
  }
}];
